-- SitePix example templates — the trades that were missing: Electrical, HVAC,
-- Plumbing.
--
-- The built-in library seeded by 20260803000001 covered reporting shapes (site
-- visit, photo log, daily report) and four verticals — insurance, restoration,
-- roofing, cleaning. A sparky, a plumber or an HVAC tech opening "More
-- Templates" found nothing addressed to the work they actually do, so every one
-- of them started from a generic site report and retyped the same readings
-- block by hand on every call.
--
-- Nine templates, three per trade, following the shape each trade's paperwork
-- already takes:
--
--   * the service call   — reported fault, findings, readings, parts, sign-off
--   * the inspection/PM  — the tick-box sheet done on a schedule
--   * the installation   — what was fitted, how it tested, warranty sign-off
--
-- They are ownerless built-ins (team_id IS NULL AND created_by IS NULL), so the
-- 20260803000000 read policy already covers them and nobody can edit one in
-- place — "Duplicate to edit" is the way in, same as the rest of the library.
--
-- Requires 20260803000000 to have run: it is what made `created_by` nullable
-- and added the unique `slug` index this file's ON CONFLICT depends on. No
-- schema change of its own, so this takes row locks only and cannot deadlock
-- against read traffic.
--
-- The category strings ('Electrical', 'HVAC', 'Plumbing') are what
-- ChoosePageTemplateDialog groups the picker by, so they must match the trade
-- order table in that component exactly.
--
-- Idempotent — ON CONFLICT (slug) DO UPDATE. Safe to re-run.
-- Apply via the SitePix Supabase SQL editor.

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-electrical-service-call',
  NULL,
  NULL,
  'Electrical Service Call Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'Electrical',
    'description', 'Troubleshoot-and-repair ticket: reported fault, what you found, voltage and current readings, parts used, before and after photos, customer signature.',
    'html', $html$<h1>Electrical Service Call</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Fill the boxes, drop in the photos, hand it over before you leave site.</span></em></p><table><tbody><tr><th><p>Customer</p></th><th><p>Contact</p></th><th><p>Work order #</p></th><th><p>On site</p></th><th><p>Off site</p></th></tr><tr><td><p>[Customer name]</p></td><td><p>[Phone]</p></td><td><p>[WO number]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td></tr></tbody></table><h2>Reported problem</h2><p><em><span style="color: rgb(140,148,162)">What did the customer call about, in their words?</span></em></p><p></p><h2>What we found</h2><p><em><span style="color: rgb(140,148,162)">The actual fault, and what caused it.</span></em></p><p></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPanel%20or%20equipment%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Panel or equipment"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EClose-up%20%E2%80%94%20the%20fault%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Close-up — the fault"></p><h2>Readings</h2><table><tbody><tr><th><p>Location / circuit</p></th><th><p>Voltage (V)</p></th><th><p>Current (A)</p></th><th><p>Notes</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Work performed</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Power isolated and locked out before work</p></li><li data-type="taskItem" data-checked="false"><p>Fault repaired or component replaced</p></li><li data-type="taskItem" data-checked="false"><p>Terminations torqued to spec</p></li><li data-type="taskItem" data-checked="false"><p>Circuit tested under load</p></li><li data-type="taskItem" data-checked="false"><p>Panel cover refitted and circuit labelled</p></li><li data-type="taskItem" data-checked="false"><p>Work area left clean and safe</p></li></ul><h2>Parts and materials</h2><table><tbody><tr><th><p>Qty</p></th><th><p>Part / material</p></th><th><p>Part #</p></th><th><p>Notes</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Photos</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After"></p><h2>Safety items to flag</h2><p><em><span style="color: rgb(140,148,162)">Anything the customer needs to know about, even if it was not this call.</span></em></p><p></p><h2>Recommended follow-up</h2><table><tbody><tr><th><p>Priority</p></th><th><p>Recommendation</p></th><th><p>Est. time</p></th><th><p>Est. cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Technician</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-electrical-panel-inspection',
  NULL,
  NULL,
  'Electrical Panel & Circuit Inspection',
  jsonb_build_object(
    'style', 'report',
    'category', 'Electrical',
    'description', 'Panel-by-panel survey with a full circuit schedule, safety condition checks and a prioritised deficiency list you can quote from.',
    'html', $html$<h1>Electrical Panel and Circuit Inspection</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">One panel per report. Photograph the panel open, then work down the schedule.</span></em></p><h2>Panel details</h2><table><tbody><tr><th><p>Panel ID</p></th><th><p>Location</p></th><th><p>Make / model</p></th><th><p>Main breaker (A)</p></th><th><p>Bus rating (A)</p></th><th><p>Volts / phase</p></th></tr><tr><td><p>[Panel ID]</p></td><td><p>[Location]</p></td><td><p>[Make and model]</p></td><td><p>[Amps]</p></td><td><p>[Amps]</p></td><td><p>[e.g. 240V 1ph]</p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPanel%20with%20cover%20removed%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Panel with cover removed"></p><h2>Circuit schedule</h2><p><em><span style="color: rgb(140,148,162)">Confirm every breaker against the legend on the door. Mark anything that does not match.</span></em></p><table><tbody><tr><th><p>Ckt #</p></th><th><p>Breaker (A)</p></th><th><p>Serves</p></th><th><p>Wire size</p></th><th><p>Condition</p></th><th><p>Action</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Condition checks</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Legend on the door matches the actual circuits</p></li><li data-type="taskItem" data-checked="false"><p>No double-tapped breakers</p></li><li data-type="taskItem" data-checked="false"><p>No missing knockouts or blank filler plates</p></li><li data-type="taskItem" data-checked="false"><p>Breakers match bus and conductor ratings</p></li><li data-type="taskItem" data-checked="false"><p>Terminations tight, no scorching or discolouration</p></li><li data-type="taskItem" data-checked="false"><p>Grounding and bonding correct and continuous</p></li><li data-type="taskItem" data-checked="false"><p>No corrosion, moisture or rodent damage</p></li><li data-type="taskItem" data-checked="false"><p>Required working clearance in front of panel</p></li><li data-type="taskItem" data-checked="false"><p>Panel dead front and cover secure</p></li></ul><h2>Deficiencies</h2><table><tbody><tr><th><p>Priority</p></th><th><p>Finding</p></th><th><p>Risk if left</p></th><th><p>Recommended fix</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDeficiency%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Deficiency 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDeficiency%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Deficiency 2"></p><h2>Summary</h2><p><em><span style="color: rgb(140,148,162)">Safe to use as-is, safe with the repairs listed, or unsafe now?</span></em></p><p></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Inspector</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-electrical-installation-test',
  NULL,
  NULL,
  'Electrical Installation & Test Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'Electrical',
    'description', 'Sign-off for new circuits: what was installed, insulation resistance, loop impedance, GFCI and AFCI test results, and a declaration to sign.',
    'html', $html$<h1>Electrical Installation and Test Report</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">The record that the new work was installed, tested and left safe.</span></em></p><h2>Scope of installation</h2><p><em><span style="color: rgb(140,148,162)">What was installed, where, and under which permit.</span></em></p><p></p><table><tbody><tr><th><p>Permit #</p></th><th><p>Inspection date</p></th><th><p>Inspector</p></th><th><p>Result</p></th></tr><tr><td><p>[Permit number]</p></td><td><p>[Date]</p></td><td><p>[Name]</p></td><td><p>[Pass / fail]</p></td></tr></tbody></table><h2>Circuits installed</h2><table><tbody><tr><th><p>Circuit</p></th><th><p>Description</p></th><th><p>Conductor size</p></th><th><p>OCPD (A)</p></th><th><p>Device type</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Test results</h2><table><tbody><tr><th><p>Test</p></th><th><p>Result</p></th><th><p>Pass / fail</p></th></tr><tr><td><p>Continuity of protective conductors</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Insulation resistance (MΩ)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Polarity</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Ground fault loop impedance (Ω)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>GFCI trip time (ms)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>AFCI function</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Voltage under load (V)</p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Test instruments</h2><table><tbody><tr><th><p>Instrument</p></th><th><p>Model</p></th><th><p>Serial</p></th><th><p>Calibration due</p></th></tr><tr><td><p>[Instrument]</p></td><td><p>[Model]</p></td><td><p>[Serial]</p></td><td><p>[Date]</p></td></tr></tbody></table><h2>Completed work</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EInstalled%20work%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Installed work"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ELabelled%20panel%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Labelled panel"></p><h2>Declaration</h2><p><em><span style="color: rgb(140,148,162)">I certify that the work described above was installed and tested by me, and complies with the applicable electrical code except where noted.</span></em></p><p></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Installing electrician</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-hvac-service-call',
  NULL,
  NULL,
  'HVAC Service Call Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'HVAC',
    'description', 'Diagnostic call sheet with the full readings block — split, pressures, superheat, subcool, static and amps — then the fix, the parts and the sign-off.',
    'html', $html$<h1>HVAC Service Call</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Readings first, then the fix. The numbers are what make this defensible later.</span></em></p><table><tbody><tr><th><p>Customer</p></th><th><p>Contact</p></th><th><p>Work order #</p></th><th><p>On site</p></th><th><p>Off site</p></th></tr><tr><td><p>[Customer name]</p></td><td><p>[Phone]</p></td><td><p>[WO number]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td></tr></tbody></table><h2>Equipment</h2><table><tbody><tr><th><p>Unit ID</p></th><th><p>Type</p></th><th><p>Make</p></th><th><p>Model</p></th><th><p>Serial</p></th><th><p>Filter size</p></th></tr><tr><td><p>[Unit]</p></td><td><p>[Type]</p></td><td><p>[Make]</p></td><td><p>[Model]</p></td><td><p>[Serial]</p></td><td><p>[Size]</p></td></tr></tbody></table><h2>Reported problem</h2><p><em><span style="color: rgb(140,148,162)">What is it doing, and since when?</span></em></p><p></p><h2>System readings</h2><table><tbody><tr><th><p>Reading</p></th><th><p>Value</p></th><th><p>Notes</p></th></tr><tr><td><p>Return air temp (°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Supply air temp (°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Temperature split (Δ°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Suction pressure (psi)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Head pressure (psi)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Superheat (°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Subcooling (°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Total external static (in. w.c.)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Compressor amps (A)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Capacitor — rated / measured (µF)</p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Diagnosis</h2><p><em><span style="color: rgb(140,148,162)">What failed, and why it failed.</span></em></p><p></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EUnit%20%2F%20nameplate%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Unit / nameplate"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EClose-up%20%E2%80%94%20the%20fault%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Close-up — the fault"></p><h2>Work performed</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Power isolated before service</p></li><li data-type="taskItem" data-checked="false"><p>Fault repaired or component replaced</p></li><li data-type="taskItem" data-checked="false"><p>Filter checked or replaced</p></li><li data-type="taskItem" data-checked="false"><p>Condensate drain cleared and flowing</p></li><li data-type="taskItem" data-checked="false"><p>Refrigerant charge verified</p></li><li data-type="taskItem" data-checked="false"><p>System cycled and confirmed operating</p></li><li data-type="taskItem" data-checked="false"><p>Thermostat set back to customer setting</p></li></ul><h2>Parts and materials</h2><table><tbody><tr><th><p>Qty</p></th><th><p>Part / material</p></th><th><p>Part #</p></th><th><p>Warranty</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Photos</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After"></p><h2>Recommendations</h2><table><tbody><tr><th><p>Priority</p></th><th><p>Recommendation</p></th><th><p>Why it matters</p></th><th><p>Est. cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Technician</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-hvac-maintenance-visit',
  NULL,
  NULL,
  'HVAC Maintenance Visit Checklist',
  jsonb_build_object(
    'style', 'report',
    'category', 'HVAC',
    'description', 'Seasonal PM sheet: indoor, outdoor, controls and safeties as tick-boxes, readings, findings to quote, and the next service date.',
    'html', $html$<h1>HVAC Maintenance Visit</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Seasonal service. Tick as you go, note the readings, photograph anything you want on record.</span></em></p><table><tbody><tr><th><p>Customer</p></th><th><p>Contact</p></th><th><p>Work order #</p></th><th><p>On site</p></th><th><p>Off site</p></th></tr><tr><td><p>[Customer name]</p></td><td><p>[Phone]</p></td><td><p>[WO number]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td></tr></tbody></table><h2>Equipment covered</h2><table><tbody><tr><th><p>Unit ID</p></th><th><p>Location</p></th><th><p>Make / model</p></th><th><p>Serial</p></th><th><p>Filter size</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Indoor unit</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Filter replaced</p></li><li data-type="taskItem" data-checked="false"><p>Blower wheel and motor inspected</p></li><li data-type="taskItem" data-checked="false"><p>Evaporator coil inspected and cleaned</p></li><li data-type="taskItem" data-checked="false"><p>Condensate drain flushed and treated</p></li><li data-type="taskItem" data-checked="false"><p>Drain pan clear, float switch tested</p></li><li data-type="taskItem" data-checked="false"><p>Belts and pulleys checked, tension set</p></li><li data-type="taskItem" data-checked="false"><p>Electrical connections tightened</p></li><li data-type="taskItem" data-checked="false"><p>Cabinet panels sealed and secure</p></li></ul><h2>Outdoor unit</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Condenser coil washed</p></li><li data-type="taskItem" data-checked="false"><p>Fan motor and blades checked</p></li><li data-type="taskItem" data-checked="false"><p>Contactor inspected for pitting</p></li><li data-type="taskItem" data-checked="false"><p>Capacitor tested against rating</p></li><li data-type="taskItem" data-checked="false"><p>Refrigerant lines and insulation checked</p></li><li data-type="taskItem" data-checked="false"><p>Disconnect and wiring inspected</p></li><li data-type="taskItem" data-checked="false"><p>Pad level, clearances clear of growth and debris</p></li></ul><h2>Controls, heating and safeties</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Thermostat operation and calibration checked</p></li><li data-type="taskItem" data-checked="false"><p>Full heat and cool cycle tested</p></li><li data-type="taskItem" data-checked="false"><p>Safety switches and limits tested</p></li><li data-type="taskItem" data-checked="false"><p>Burners and flame sensor cleaned</p></li><li data-type="taskItem" data-checked="false"><p>Heat exchanger inspected for cracks</p></li><li data-type="taskItem" data-checked="false"><p>Gas pressure checked</p></li><li data-type="taskItem" data-checked="false"><p>Flue and combustion air verified clear</p></li><li data-type="taskItem" data-checked="false"><p>Carbon monoxide checked at the supply</p></li></ul><h2>Readings</h2><table><tbody><tr><th><p>Reading</p></th><th><p>Value</p></th><th><p>Notes</p></th></tr><tr><td><p>Temperature split (Δ°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Total external static (in. w.c.)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Capacitor — rated / measured (µF)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Compressor amps (A)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Refrigerant — superheat / subcool</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>CO at supply (ppm)</p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Photos</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%20service%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before service"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%20service%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After service"></p><h2>Findings and recommended repairs</h2><table><tbody><tr><th><p>Priority</p></th><th><p>Finding</p></th><th><p>Recommended action</p></th><th><p>Est. cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>System status</h2><p><em><span style="color: rgb(140,148,162)">Operating normally, operating with the faults listed, or needs work before next use?</span></em></p><p></p><table><tbody><tr><th><p>Next service due</p></th><th><p>Filter size to order</p></th><th><p>Plan</p></th></tr><tr><td><p>[Date]</p></td><td><p>[Size]</p></td><td><p>[Plan name]</p></td></tr></tbody></table><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Technician</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
