    'html', $html$<h1>HVAC Installation and Start-Up</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Everything the manufacturer wants on file for the warranty, in one page.</span></em></p><h2>Equipment installed</h2><table><tbody><tr><th><p>Item</p></th><th><p>Make</p></th><th><p>Model</p></th><th><p>Serial</p></th><th><p>Warranty registered</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Equipment removed</h2><table><tbody><tr><th><p>Item</p></th><th><p>Make / model</p></th><th><p>Serial</p></th><th><p>Disposal</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Installation</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Line set pressure tested and held</p></li><li data-type="taskItem" data-checked="false"><p>System evacuated to 500 microns and held</p></li><li data-type="taskItem" data-checked="false"><p>Refrigerant charge weighed in and recorded</p></li><li data-type="taskItem" data-checked="false"><p>Condensate routed, trapped and draining</p></li><li data-type="taskItem" data-checked="false"><p>Disconnect and breaker sized to nameplate</p></li><li data-type="taskItem" data-checked="false"><p>Duct connections sealed and supported</p></li><li data-type="taskItem" data-checked="false"><p>Equipment level, secured and clear of obstruction</p></li><li data-type="taskItem" data-checked="false"><p>Thermostat installed and configured</p></li><li data-type="taskItem" data-checked="false"><p>New filter installed</p></li><li data-type="taskItem" data-checked="false"><p>Permit posted and inspection scheduled</p></li></ul><h2>Start-up readings</h2><table><tbody><tr><th><p>Reading</p></th><th><p>Value</p></th><th><p>Spec</p></th><th><p>In range</p></th></tr><tr><td><p>Line voltage (V)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Compressor amps (A)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Suction pressure (psi)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Head pressure (psi)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Superheat (°F)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Subcooling (°F)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Refrigerant charge (lb / oz)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Temperature split (Δ°F)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Total external static (in. w.c.)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Gas manifold pressure (in. w.c.)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Airflow</h2><table><tbody><tr><th><p>Zone / register</p></th><th><p>Design CFM</p></th><th><p>Measured CFM</p></th><th><p>Balanced</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Photos</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EIndoor%20unit%20installed%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Indoor unit installed"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EOutdoor%20unit%20installed%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Outdoor unit installed"></p><h2>Customer walkthrough</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Thermostat operation demonstrated</p></li><li data-type="taskItem" data-checked="false"><p>Filter type, size and change interval explained</p></li><li data-type="taskItem" data-checked="false"><p>Warranty terms and registration explained</p></li><li data-type="taskItem" data-checked="false"><p>Maintenance plan offered</p></li><li data-type="taskItem" data-checked="false"><p>Manuals and paperwork handed over</p></li></ul><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Installer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
