INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-plumbing-leak-investigation',
  NULL,
  NULL,
  'Plumbing Leak Investigation & Repair',
  jsonb_build_object(
    'style', 'report',
    'category', 'Plumbing',
    'description', 'For water calls that turn into a claim: detection method, source, moisture readings, affected areas, what was made safe, and what still needs doing.',
    'html', $html$<h1>Plumbing Leak Investigation and Repair</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Where the water came from, how far it got, and what stopped it.</span></em></p><table><tbody><tr><th><p>Customer</p></th><th><p>Contact</p></th><th><p>Work order #</p></th><th><p>On site</p></th><th><p>Off site</p></th></tr><tr><td><p>[Customer name]</p></td><td><p>[Phone]</p></td><td><p>[WO number]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td></tr></tbody></table><table><tbody><tr><th><p>Water shut off at</p></th><th><p>Time shut off</p></th><th><p>Time on site</p></th><th><p>Still active on arrival</p></th></tr><tr><td><p>[Location]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td><td><p>[Yes / no]</p></td></tr></tbody></table><h2>How we looked</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Visual inspection</p></li><li data-type="taskItem" data-checked="false"><p>Moisture meter</p></li><li data-type="taskItem" data-checked="false"><p>Thermal imaging camera</p></li><li data-type="taskItem" data-checked="false"><p>Acoustic leak detection</p></li><li data-type="taskItem" data-checked="false"><p>Drain line camera</p></li><li data-type="taskItem" data-checked="false"><p>Pressure test on supply</p></li><li data-type="taskItem" data-checked="false"><p>Dye test</p></li></ul><h2>Source of the leak</h2><p><em><span style="color: rgb(140,148,162)">The exact component and location. Be specific enough that another tech could find it.</span></em></p><p></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ESource%20of%20leak%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Source of leak"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EResulting%20damage%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Resulting damage"></p><h2>Moisture readings</h2><table><tbody><tr><th><p>Location</p></th><th><p>Material</p></th><th><p>Reading (%)</p></th><th><p>Dry standard</p></th><th><p>Wet</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Affected areas</h2><table><tbody><tr><th><p>Area</p></th><th><p>Materials affected</p></th><th><p>Extent</p></th><th><p>Action needed</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Made safe on the day</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Water isolated</p></li><li data-type="taskItem" data-checked="false"><p>Standing water extracted</p></li><li data-type="taskItem" data-checked="false"><p>Contents moved clear</p></li><li data-type="taskItem" data-checked="false"><p>Affected area contained</p></li><li data-type="taskItem" data-checked="false"><p>Drying equipment placed</p></li><li data-type="taskItem" data-checked="false"><p>Customer advised to notify their insurer</p></li></ul><h2>Repair performed</h2><p><em><span style="color: rgb(140,148,162)">What was repaired now, and what is still outstanding.</span></em></p><p></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ERepair%20in%20progress%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Repair in progress"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ERepair%20complete%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Repair complete"></p><h2>Recommended next steps</h2><table><tbody><tr><th><p>Priority</p></th><th><p>Recommendation</p></th><th><p>Trade</p></th><th><p>Est. cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Technician</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-plumbing-installation-signoff',
  NULL,
  NULL,
  'Water Heater & Fixture Installation',
  jsonb_build_object(
    'style', 'report',
    'category', 'Plumbing',
    'description', 'Installation sign-off with the code checklist — T&P, expansion tank, gas and flue — plus tests, warranty details and the customer''s signature.',
    'html', $html$<h1>Water Heater and Fixture Installation</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">The code checks, the tests and the customer's signature in one place.</span></em></p><h2>Equipment installed</h2><table><tbody><tr><th><p>Item</p></th><th><p>Make</p></th><th><p>Model</p></th><th><p>Serial</p></th><th><p>Capacity</p></th><th><p>Warranty</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Equipment removed</h2><table><tbody><tr><th><p>Item</p></th><th><p>Make / model</p></th><th><p>Age</p></th><th><p>Disposal</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Installation and code checks</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>T&amp;P relief valve fitted, discharge piped to code</p></li><li data-type="taskItem" data-checked="false"><p>Expansion tank installed and pre-charged to supply pressure</p></li><li data-type="taskItem" data-checked="false"><p>Drip pan installed and drained</p></li><li data-type="taskItem" data-checked="false"><p>Seismic strapping fitted where required</p></li><li data-type="taskItem" data-checked="false"><p>Shutoff valve accessible and operating</p></li><li data-type="taskItem" data-checked="false"><p>Dielectric unions used at dissimilar metals</p></li><li data-type="taskItem" data-checked="false"><p>Gas line sized, sediment trap fitted, leak tested</p></li><li data-type="taskItem" data-checked="false"><p>Flue draft tested, combustion air adequate</p></li><li data-type="taskItem" data-checked="false"><p>Condensate routed and neutralised</p></li><li data-type="taskItem" data-checked="false"><p>Thermostat set to a safe delivery temperature</p></li><li data-type="taskItem" data-checked="false"><p>Permit obtained and inspection scheduled</p></li></ul><h2>Tests</h2><table><tbody><tr><th><p>Test</p></th><th><p>Result</p></th><th><p>Pass / fail</p></th></tr><tr><td><p>Water leak test at all joints</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Gas leak test</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Flue draft test</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Static water pressure (psi)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Thermostat setpoint (°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Delivered temperature at fixture (°F)</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>T&amp;P valve operation</p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Photos</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EInstalled%20unit%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Installed unit"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EData%20plate%20%2F%20serial%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Data plate / serial"></p><h2>Customer walkthrough</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Shutoff and isolation valves shown</p></li><li data-type="taskItem" data-checked="false"><p>Thermostat adjustment explained</p></li><li data-type="taskItem" data-checked="false"><p>Anode rod and flushing interval explained</p></li><li data-type="taskItem" data-checked="false"><p>Warranty terms and registration explained</p></li><li data-type="taskItem" data-checked="false"><p>Manuals and paperwork handed over</p></li></ul><table><tbody><tr><th><p>Permit #</p></th><th><p>Inspection date</p></th><th><p>Warranty — parts</p></th><th><p>Warranty — labour</p></th></tr><tr><td><p>[Permit number]</p></td><td><p>[Date]</p></td><td><p>[Years]</p></td><td><p>[Years]</p></td></tr></tbody></table><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Installer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

-- === VERIFY ================================================================
-- Expect 9 — three templates in each of the three new trades.
SELECT body->>'category' AS category, count(*) AS templates
FROM public.document_templates
WHERE team_id IS NULL
  AND created_by IS NULL
  AND archived = false
  AND body->>'category' IN ('Electrical', 'HVAC', 'Plumbing')
GROUP BY 1
ORDER BY 1;

-- Every one carries a description and a body — a blank either way is what an
-- empty picker row looks like.
SELECT count(*) AS complete
FROM public.document_templates
WHERE (slug LIKE 'sitepix-electrical-%'
    OR slug LIKE 'sitepix-hvac-%'
    OR slug LIKE 'sitepix-plumbing-%')
  AND coalesce(body->>'description', '') <> ''
  AND coalesce(body->>'html', '') <> '';
